function compute(inputs) {
  const Vmax = inputs.Vmax;
  const Km = inputs.Km;
  const S = inputs.S;
  const v = (Vmax * S) / (Km + S);
  const v_at_Km = Vmax / 2;
  const S_values = [];
  const v_values = [];
  for (let i = 0; i <= 100; i++) {
    const s = (i / 100) * 20;
    S_values.push(s);
    v_values.push((Vmax * s) / (Km + s));
  }
  const curve = { x: S_values, lines: [{ name: 'v', y: v_values }], marker: { x: S, y: v } };
  const table = {
    columns: ['Quantity', 'Value'],
    rows: [
      ['Vmax', Vmax.toFixed(2)],
      ['Km', Km.toFixed(2)],
      ['[S]', S.toFixed(2)],
      ['v', v.toFixed(4)],
      ['Vmax/2', v_at_Km.toFixed(4)],
      ['v at [S]=Km', v_at_Km.toFixed(4)]
    ]
  };
  let insight = '';
  if (S === 0) {
    insight = 'At [S]=0, the rate is 0. As [S] increases, v increases.';
  } else if (Math.abs(S - Km) < 0.01) {
    insight = 'At [S]=Km, the rate is exactly half of Vmax: v = Vmax/2 = ' + v_at_Km.toFixed(2) + '.';
  } else if (S > 10 * Km) {
    insight = 'At high [S] (>> Km), the rate approaches Vmax = ' + Vmax.toFixed(2) + '. Currently v = ' + v.toFixed(2) + ', which is ' + ((v / Vmax) * 100).toFixed(1) + '% of Vmax.';
  } else {
    insight = 'The rate is ' + v.toFixed(2) + '. At [S]=Km, the rate would be ' + v_at_Km.toFixed(2) + ' (half of Vmax).';
  }
  return {
    v: v,
    v_at_Km: v_at_Km,
    curve: curve,
    table: table,
    insight: insight
  };
}
